# --- 1000 GRADIENT BOX STYLES ---
def gradient_box_0(text):
    c1, c2 = MEGA_PALETTES['palette_0']
    print(gradient_text('╔' + '═'*40 + '╗', c1, c2))
    print(gradient_text('║ ', c1, c2) + text.center(38) + gradient_text(' ║', c1, c2))
    print(gradient_text('╚' + '═'*40 + '╝', c1, c2))

